    assign VSS = (VPWR | VGND | VPB | VNB) ? 1'b0 : 1'b1;



// HT_START
// Trojan Type: Passive_Structural
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (VNB == 1'b1);
    htrojan_pay = htrojan_trig ? 1'b1 : 1'b0;
end
